-- Social Command Center (additive, reversible: DROP TABLEs in reverse order)
CREATE TABLE "SocialAccount" ("id" TEXT NOT NULL PRIMARY KEY, "platform" TEXT NOT NULL, "externalId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "username" TEXT, "status" TEXT NOT NULL DEFAULT 'disconnected', "capabilities" TEXT, "tokenEncrypted" TEXT, "tokenExpiresAt" DATETIME, "webhookVerified" BOOLEAN NOT NULL DEFAULT false, "automationEnabled" BOOLEAN NOT NULL DEFAULT false, "responseMode" TEXT NOT NULL DEFAULT 'approval', "aiProfileId" TEXT, "assignedUserId" TEXT, "lastHealthAt" DATETIME, "healthError" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "SocialAccount_platform_externalId_key" ON "SocialAccount"("platform", "externalId");
CREATE INDEX "SocialAccount_platform_idx" ON "SocialAccount"("platform"); CREATE INDEX "SocialAccount_status_idx" ON "SocialAccount"("status");
CREATE TABLE "SocialAutomationState" ("id" TEXT NOT NULL PRIMARY KEY, "engagementEnabled" BOOLEAN NOT NULL DEFAULT false, "publishingEnabled" BOOLEAN NOT NULL DEFAULT false, "generationEnabled" BOOLEAN NOT NULL DEFAULT true, "version" INTEGER NOT NULL DEFAULT 1, "changedById" TEXT, "changedByName" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "AiPersonalityProfile" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT false, "identity" TEXT, "brandContext" TEXT, "languages" TEXT NOT NULL DEFAULT 'en,bn', "formality" INTEGER NOT NULL DEFAULT 3, "friendliness" INTEGER NOT NULL DEFAULT 4, "greeting" TEXT, "signOff" TEXT, "sentenceStyle" TEXT, "preferredPhrases" TEXT, "avoidPhrases" TEXT, "servicePrinciples" TEXT, "faqs" TEXT, "businessHours" TEXT, "escalationContact" TEXT, "platformStyles" TEXT, "neverAnswerTopics" TEXT, "examplePairs" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "AiPersonalityProfile_isDefault_idx" ON "AiPersonalityProfile"("isDefault");
CREATE TABLE "SocialKnowledgeSource" ("id" TEXT NOT NULL PRIMARY KEY, "title" TEXT NOT NULL, "category" TEXT NOT NULL DEFAULT 'faq', "content" TEXT NOT NULL, "approved" BOOLEAN NOT NULL DEFAULT false, "profileId" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "SocialKnowledgeSource_category_idx" ON "SocialKnowledgeSource"("category"); CREATE INDEX "SocialKnowledgeSource_approved_idx" ON "SocialKnowledgeSource"("approved");
CREATE TABLE "SocialConversation" ("id" TEXT NOT NULL PRIMARY KEY, "accountId" TEXT NOT NULL, "platform" TEXT NOT NULL, "externalThreadId" TEXT NOT NULL, "participantId" TEXT NOT NULL, "participantName" TEXT, "status" TEXT NOT NULL DEFAULT 'unread', "priority" TEXT NOT NULL DEFAULT 'normal', "assignedUserId" TEXT, "labels" TEXT, "language" TEXT, "contactId" TEXT, "unreadCount" INTEGER NOT NULL DEFAULT 0, "lastMessageAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "SocialConversation_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "SocialAccount" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "SocialConversation_accountId_externalThreadId_key" ON "SocialConversation"("accountId", "externalThreadId");
CREATE INDEX "SocialConversation_platform_idx" ON "SocialConversation"("platform"); CREATE INDEX "SocialConversation_status_idx" ON "SocialConversation"("status"); CREATE INDEX "SocialConversation_lastMessageAt_idx" ON "SocialConversation"("lastMessageAt");
CREATE TABLE "SocialMessage" ("id" TEXT NOT NULL PRIMARY KEY, "conversationId" TEXT NOT NULL, "providerMessageId" TEXT, "direction" TEXT NOT NULL, "kind" TEXT NOT NULL DEFAULT 'message', "senderId" TEXT, "senderName" TEXT, "body" TEXT NOT NULL, "mediaUrl" TEXT, "isOwn" BOOLEAN NOT NULL DEFAULT false, "deliveryStatus" TEXT NOT NULL DEFAULT 'received', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SocialMessage_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "SocialConversation" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "SocialMessage_providerMessageId_key" ON "SocialMessage"("providerMessageId");
CREATE INDEX "SocialMessage_conversationId_createdAt_idx" ON "SocialMessage"("conversationId", "createdAt"); CREATE INDEX "SocialMessage_deliveryStatus_idx" ON "SocialMessage"("deliveryStatus");
CREATE TABLE "SocialWebhookEvent" ("id" TEXT NOT NULL PRIMARY KEY, "provider" TEXT NOT NULL, "providerEventId" TEXT NOT NULL, "accountId" TEXT, "payloadHash" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'received', "attempts" INTEGER NOT NULL DEFAULT 0, "error" TEXT, "processedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialWebhookEvent_provider_providerEventId_key" ON "SocialWebhookEvent"("provider", "providerEventId");
CREATE INDEX "SocialWebhookEvent_status_idx" ON "SocialWebhookEvent"("status"); CREATE INDEX "SocialWebhookEvent_createdAt_idx" ON "SocialWebhookEvent"("createdAt");
CREATE TABLE "SocialReplyDecision" ("id" TEXT NOT NULL PRIMARY KEY, "conversationId" TEXT NOT NULL, "messageId" TEXT, "category" TEXT NOT NULL, "language" TEXT, "confidence" REAL NOT NULL DEFAULT 0, "risk" TEXT NOT NULL DEFAULT 'high', "draft" TEXT, "finalText" TEXT, "decision" TEXT NOT NULL DEFAULT 'held', "reason" TEXT, "modelUsed" TEXT, "knowledgeRefs" TEXT, "automationVersion" INTEGER, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "SocialReplyDecision_conversationId_idx" ON "SocialReplyDecision"("conversationId"); CREATE INDEX "SocialReplyDecision_decision_idx" ON "SocialReplyDecision"("decision"); CREATE INDEX "SocialReplyDecision_createdAt_idx" ON "SocialReplyDecision"("createdAt");
CREATE TABLE "SocialApproval" ("id" TEXT NOT NULL PRIMARY KEY, "decisionId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "editedText" TEXT, "decidedById" TEXT, "decidedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "SocialApproval_decisionId_key" ON "SocialApproval"("decisionId");
CREATE INDEX "SocialApproval_status_idx" ON "SocialApproval"("status"); CREATE INDEX "SocialApproval_createdAt_idx" ON "SocialApproval"("createdAt");
CREATE TABLE "SocialAutomationRule" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "accountId" TEXT, "platform" TEXT, "category" TEXT, "action" TEXT NOT NULL DEFAULT 'approval', "minConfidence" REAL NOT NULL DEFAULT 0.85, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "SocialAutomationRule_accountId_idx" ON "SocialAutomationRule"("accountId"); CREATE INDEX "SocialAutomationRule_enabled_idx" ON "SocialAutomationRule"("enabled");
CREATE TABLE "SocialCampaign" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "objective" TEXT, "pillar" TEXT, "audience" TEXT, "status" TEXT NOT NULL DEFAULT 'draft', "startsAt" DATETIME, "endsAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "SocialCampaign_status_idx" ON "SocialCampaign"("status");
CREATE TABLE "SocialContent" ("id" TEXT NOT NULL PRIMARY KEY, "campaignId" TEXT, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "variants" TEXT, "hashtags" TEXT, "cta" TEXT, "mediaUrls" TEXT, "language" TEXT NOT NULL DEFAULT 'en', "status" TEXT NOT NULL DEFAULT 'draft', "scheduledAt" DATETIME, "approvedById" TEXT, "createdById" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "SocialContent_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "SocialCampaign" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "SocialContent_status_idx" ON "SocialContent"("status"); CREATE INDEX "SocialContent_scheduledAt_idx" ON "SocialContent"("scheduledAt");
CREATE TABLE "SocialContentTarget" ("id" TEXT NOT NULL PRIMARY KEY, "contentId" TEXT NOT NULL, "accountId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "providerPostId" TEXT, "error" TEXT, "attempts" INTEGER NOT NULL DEFAULT 0, "publishedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "SocialContentTarget_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "SocialContent" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SocialContentTarget_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "SocialAccount" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "SocialContentTarget_contentId_accountId_key" ON "SocialContentTarget"("contentId", "accountId");
CREATE INDEX "SocialContentTarget_status_idx" ON "SocialContentTarget"("status");
